  c = mix(c, mix(L(0.09, 0.18, 0.08), L(0.16, 0.28, 0.13), leaf), clover * 0.8);
  c = mix(c, L(0.2, 0.27, 0.07) * (0.7 + 0.6 * fine), moss * 0.5);
  c = mix(c, soil, clamp(soilK, 0.0, 1.0));
